// One table slot: a funcref (type key + the Go func value) or nil for a null slot. call_indirect compares type keys, so a table shared across modules stays consistent.
type funcref struct {
	ty string
	fn any
}

type Table struct {
	slots []*funcref
}

func newTable(size uint32) *Table {
	return &Table{slots: make([]*funcref, size)}
}

func (t *Table) size() uint32 {
	return uint32(len(t.slots))
}

// The caller type-asserts the returned func value to the exact signature of the call site.
func (t *Table) call(i uint32, typeKey string) any {
	if i >= uint32(len(t.slots)) {
		Rt.trap("undefined element")
	}
	slot := t.slots[i]
	if slot == nil {
		Rt.trap("uninitialized element")
	}
	if slot.ty != typeKey {
		Rt.trap("indirect call type mismatch")
	}
	return slot.fn
}

func (t *Table) check_range(offset, count uint32) {
	if uint64(offset)+uint64(count) > uint64(len(t.slots)) {
		Rt.trap("out of bounds table access")
	}
}

// `elem` is a list of table slot values, built at instantiation/table.init.
func (t *Table) init(dst uint32, elem []*funcref, src, length uint32) {
	if uint64(src)+uint64(length) > uint64(len(elem)) {
		Rt.trap("out of bounds table access")
	}
	t.check_range(dst, length)
	if length == 0 {
		return
	}
	copy(t.slots[dst:dst+length], elem[src:src+length])
}

